package com.angle.trading.security;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.context.event.EventListener;import org.springframework.security.authentication.event.AbstractAuthenticationFailureEvent;import org.springframework.stereotype.Component;@Componentpublic class LoginFailureListener {    private static final Logger log =            LoggerFactory.getLogger(LoginFailureListener.class);    @EventListener    public void onFailure(AbstractAuthenticationFailureEvent event) {        log.info("AuthenticationFailureEvent Triggered");    }}